import idle.core.*;import idle.core.upgrades.*;import idle.core.darkmatter.*;import idle.core.bigbang.*;import java.util.*;
public class RobotPhase7 {
 static void particle(Game g){for(int i=0;i<1200;i++){Upgrade b=null;for(Upgrade u:g.upgrades(Resource.PARTICLES))if(g.canBuy(u.id())&&(b==null||g.costOf(u.id()).lt(g.costOf(b.id()))))b=u;if(b==null)break;g.buy(b.id());}}
 static void atom(Game g){for(int i=0;i<150;i++){Upgrade b=null;for(Upgrade u:g.upgrades(Resource.ATOMS))if(!u.id().equals("atom_keep")&&g.canBuy(u.id())&&(b==null||g.costOf(u.id()).lt(g.costOf(b.id()))))b=u;if(b==null)break;g.buy(b.id());}}
 static void dark(Game g){for(int i=0;i<100;i++){boolean bought=false;for(DarkUpgrade u:g.darkUpgrades())if(g.canBuyDark(u.id())){g.buyDark(u.id());bought=true;break;}if(!bought)break;}}
 public static void main(String[]args){long seed=args.length>0?Long.parseLong(args[0]):1;int hours=args.length>1?Integer.parseInt(args[1]):12;String policy=args.length>2?args[2]:"early";Game g=new Game(new GameState(),Upgrades.DEFAULT,Automations.DEFAULT,DarkUpgrades.DEFAULT,idle.core.achievements.Achievements.DEFAULT,new Random(seed));g.start();int previousChallenge=0;long prevExplosion=0;for(int tick=1;tick<=hours*3600;tick++){g.tick(1);particle(g);for(int i=0;i<5&&g.canFuse();i++){g.fuse();atom(g);particle(g);}for(Automation a:g.automations())if(g.canBuyAutomation(a.id()))g.buyAutomation(a.id());for(Automation a:g.automations())if(g.canSpeedUpAutomation(a.id()))g.speedUpAutomation(a.id());atom(g);for(int i=0;i<15&&g.canSynthesize();i++)g.synthesize();dark(g);if(!g.inChallenge()&& !policy.equals("never") && (policy.equals("early") || g.state().explosions()>=40 && g.darkLevelOf("dark_density")>=2)) {for(Challenge c:g.challenges())if(g.isChallengeUnlocked(c.id())&&!g.isChallengeCompleted(c.id())){if(g.startChallenge(c.id()))System.out.printf("START,%d,%s,%d,%s%n",tick,c.id(),g.state().explosions(),g.state().darkMatter());break;}}if(g.canExplode() && (g.inChallenge() || g.state().explosions()<40 || g.darkLevelOf("dark_density")>=2)){String c=g.inChallenge()?g.activeChallenge().id():"ordinary";g.explode();if(g.state().explosions()<=15||g.state().explosions()%5==0||!c.equals("ordinary"))System.out.printf("EXP,%d,%d,%s,%s,%d,%d%n",tick,g.state().explosions(),c,g.state().darkMatter(),g.completedChallenges(),g.achievementCount());}if(g.canBigBang()){System.out.printf("BIGBANG_READY,%d,%d,%s%n",tick,g.state().explosions(),g.state().darkMatter());break;}if(tick%3600==0){StringBuilder cond=new StringBuilder();for(BigBangCondition c:g.bigBangConditions())cond.append(c.name()).append(":").append(g.isBigBangConditionMet(c)?"Y":"N").append(" ");System.out.printf("HOUR,%d,%d,%s,%d,%d,%d,%s%n",tick/3600,g.state().explosions(),g.state().darkMatter(),g.completedChallenges(),g.achievementCount(),g.discoveredElements(),cond);}}System.out.printf("END,%d,%d,%s,%d,%d density=%d swarm=%d seeds=%d mass=%d pps=%s speed=%d gen=%d%n",hours,g.state().explosions(),g.state().darkMatter(),g.completedChallenges(),g.achievementCount(),g.darkLevelOf("dark_density"),g.darkLevelOf("dark_swarm"),g.darkLevelOf("dark_seeds"),g.darkLevelOf("dark_mass"),g.productionPerSecond(),g.levelOf("speed"),g.levelOf("generator"));}
}
